import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.DYYBR_aZ.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"tools/wps隐藏标记和win命令行换行.md","filePath":"tools/wps隐藏标记和win命令行换行.md"}'),p={name:"tools/wps隐藏标记和win命令行换行.md"};function n(r,e,_,i,l,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h3 id="wps隐藏标记" tabindex="-1">wps隐藏标记 <a class="header-anchor" href="#wps隐藏标记" aria-label="Permalink to &quot;wps隐藏标记&quot;">​</a></h3><p>如何在wps中省略换行符这些东西？</p><p>===》</p><p>如果你只是觉得文档里显示的灰色回车符（↵）或换行符（↓）碍眼，想让它“看不见”，但保留排版格式：</p><p>点击 “开始” 选项卡。找到 “显示/隐藏编辑标记” 按钮（图标通常是一个弯曲的箭头 ↵）。</p><p>点击该按钮旁边的下拉箭头，取消勾选 “显示/隐藏段落标记” 或 “显示所有格式标记”。</p><p>这样，文档中的换行符号就会在页面上消失，只保留文字。</p><h3 id="win命令行换行问题" tabindex="-1">win命令行换行问题 <a class="header-anchor" href="#win命令行换行问题" aria-label="Permalink to &quot;win命令行换行问题&quot;">​</a></h3><p>PowerShell 的命令格式，使用了反引号 进行换行。</p><p>CMD，需要将反引号 替换为插入符号 ^。</p><ul><li><strong>规则</strong>：反引号 <code></code> 后面<strong>绝对不能有任何字符</strong>，连空格都不行，必须直接按回车。</li></ul>',11)])])}const h=t(p,[["render",n]]);export{w as __pageData,h as default};
